}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    long long modulus, target;
    cin >> n >> modulus >> target;
    vector<long long> values(n);
    for (long long &value : values) {
        cin >> value;
        value %= modulus;
    }
    long long answer = 0;
    for (int first = 0; first < n - 4; ++first) {
        for (int second = first + 1; second < n - 3; ++second) {
            long long productTwo = values[first] * values[second] % modulus;
            for (int third = second + 1; third < n - 2; ++third) {
                long long productThree = productTwo * values[third] % modulus;
                for (int fourth = third + 1; fourth < n - 1; ++fourth) {
                    long long productFour = productThree * values[fourth] % modulus;
                    for (int fifth = fourth + 1; fifth < n; ++fifth) {
                        if (productFour * values[fifth] % modulus == target) ++answer;
                    }
                }
            }
        }
    }
    cout << answer << '\n';
}

#include <bits/stdc++.h>
using namespace std;

int nextState(int value) {
    int digitSum = 0;
    for (int digits = value; digits > 0; digits /= 10) {
        digitSum += digits % 10;
    }
    return (value + digitSum) % 100000;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int initial;
    long long steps;
    cin >> initial >> steps;
    vector<int> firstVisit(100000, -1), trajectory;
    int current = initial;
    while (firstVisit[current] == -1) {
        firstVisit[current] = static_cast<int>(trajectory.size());
        trajectory.push_back(current);
        current = nextState(current);
    }
    long long index = steps;
    if (steps >= static_cast<long long>(trajectory.size())) {
        int cycleStart = firstVisit[current];
        int cycleLength = static_cast<int>(trajectory.size()) - cycleStart;
        index = cycleStart + (steps - cycleStart) % cycleLength;
    }
    cout << trajectory[index] << '\n';
}

