#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, queryCount;
    cin >> n >> queryCount;
    vector<long long> height(n + 1), difference(n + 1);
    for (int i = 1; i <= n; ++i) cin >> height[i];
    long long totalVariation = 0;
    for (int i = 1; i < n; ++i) {
        difference[i] = height[i + 1] - height[i];
        totalVariation += llabs(difference[i]);
    }
    auto changeBoundary = [&](int position, long long delta) {
        totalVariation -= llabs(difference[position]);
        difference[position] += delta;
        totalVariation += llabs(difference[position]);
    };
    while (queryCount--) {
        int left, right;
        long long delta;
        cin >> left >> right >> delta;
        if (left > 1) changeBoundary(left - 1, delta);
        if (right < n) changeBoundary(right, -delta);
        cout << totalVariation << '\n';
    }
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    string numeral;
    int iterations;
    cin >> numeral >> iterations;
    while (iterations--) {
        long long value = 0;
        for (char digit : numeral) value = value * 8 + (digit - '0');
        string converted;
        do {
            int digit = static_cast<int>(value % 9);
            if (digit == 8) digit = 5;
            converted.push_back(static_cast<char>('0' + digit));
            value /= 9;
        } while (value > 0);
        reverse(converted.begin(), converted.end());
        numeral = converted;
    }
    cout << numeral << '\n';
}
